text"},"elements":[],"widgetType":"text-editor"},{"id":"6b4cb24","elType":"widget","settings":{"text":"","link":{"url":"https://darkblue-kudu-638106.hostingersite.com/towing-service-birmingham/","custom_attributes":"aria-label|Learn more about Birmingham Towing"},"selected_icon":{"value":"fas fa-arrow-right","library":"fa-solid"},"_css_classes":"x-sc-go"},"elements":[],"widgetType":"button"}],"isInner":true}],"isInner":true},{"id":"2e44158","elType":"container","settings":{"content_width":"full","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true},"css_classes":"x-sc rv rv-d2 x-dc e-no-lazyload","flex_direction":"column"},"elements":[{"id":"1e27a1c","elType":"widget","settings":{"image":{"url":"https://aadrecovery.co.uk/wp-content/uploads/2026/09/IMG_20260327_110403_860-1024x768.webp","id":611},"image_size":"full","_css_classes":"x-sc-bg"},"elements":[],"widgetType":"image"},{"id":"9227665","elType":"widget","settings":{"html":"<span class="x-sc-num">03</span>"},"elements":[],"widgetType":"html"},{"id":"ae97ba9","elType":"container","settings":{"content_width":"full","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true},"css_classes":"x-sc-body x-dc e-no-lazyload","flex_direction":"column"},"elements":[{"id":"4ef8aa3","elType":"widget","settings":{"title":"Flatbed Recovery","header_size":"h3","_css_classes":"x-h x-sc-title"},"elements":[],"widgetType":"heading"},{"id":"8f6d055","elType":"widget","settings":{"editor":"<p>Flatbed recovery is the safest way to move a vehicle that can't or shouldn't be driven  whether it's a low-clearance car, a vehicle with steering or transmission damage, or one that's been in an accident. We load, secure, and transport your car without it touching the ground, avoiding further damage on the journey.</p>","_css_classes":"x-t x-sc-text"},"elements":[],"widgetType":"text-editor"},{"id":"d0eda82","elType":"widget","settings":{"text":"","link":{"url":"https://darkblue-kudu-638106.hostingersite.com/flatbed-recovery-birmingham/","custom_attributes":"aria-label|Learn more about Flatbed Recovery"},"selected_icon":{"value":"fas fa-arrow-right","library":"fa-solid"},"_css_classes":"x-sc-go"},"elements":[],"widgetType":"button"}],"isInner":true}],"isInner":true},{"id":"18f135d","elType":"container","settings":{"content_width":"full","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true},"css_classes":"x-sc rv rv-d3 x-dc e-no-lazyload","flex_direction":"column"},"elements":[{"id":"1a61dbe","elType":"widget","settings":{"image":{"url":"https://aadrecovery.co.uk/wp-content/uploads/2026/09/IMG_20251019_143403_032-768x1024.webp","id":597},"image_size":"full","_css_classes":"x-sc-bg"},"elements":[],"widgetType":"image"},{"id":"94e3bf9","elType":"widget","settings":{"html":"<span class="x-sc-num">04</span>"},"elements":[],"widgetType":"html"},{"id":"5f55720","elType":"container","settings":{"content_width":"full","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true},"css_classes":"x-sc-body x-dc e-no-lazyload","flex_direction":"column"},"elements":[{"id":"923a736","elType":"widget","settings":{"title":"Accident Recovery","header_size":"h3","_css_classes":"x-h x-sc-title"},"elements":[],"widgetType":"heading"},{"id":"a38fd54","elType":"widget","settings":{"editor":"<p>Being involved in an accident is stressful enough without worrying about your vehicle. AAD Transport & Recovery provides accident recovery services across Birmingham, clearing your vehicle from the scene safely and taking it to a garage, insurance-approved bodyshop, or your chosen location. We work calmly and efficiently, understanding this is a difficult moment for you.</p>","_css_classes":"x-t x-sc-text"},"elements":[],"widgetType":"text-editor"},{"id":"301850c","elType":"widget","settings":{"text":"","link":{"url":"https://darkblue-kudu-638106.hostingersite.com/accident-recovery-birmingham/","custom_attributes":"aria-label|Learn more about Accident Recovery"},"selected_icon":{"value":"fas fa-arrow-right","library":"fa-solid"},"_css_classes":"x-sc-go"},"elements":[],"widgetType":"button"}],"isInner":true}],"isInner":true},{"id":"34b9b5d","elType":"container","settings":{"content_width":"full","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true},"css_classes":"x-sc rv rv-d0 x-dc e-no-lazyload","flex_direction":"column"},"elements":[{"id":"8c38fb2","elType":"widget","settings":{"image":{"url":"https://aadrecovery.co.uk/wp-content/uploads/2026/09/IMG_20250802_011544_427-1-1024x768.webp","id":578},"image_size":"full","_css_classes":"x-sc-bg"},"elements":[],"widgetType":"image"},{"id":"b64ce42","elType":"widget","settings":{"html":"<span class="x-sc-num">05</span>"},"elements":[],"widgetType":"html"},{"id":"9e7769b","elType":"container","settings":{"content_width":"full","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true},"css_classes":"x-sc-body x-dc e-no-lazyload","flex_direction":"column"},"elements":[{"id":"1012f03","elType":"widget","settings":{"title":"Wheel-Lift Recovery","header_size":"h3","_css_classes":"x-h x-sc-title"},"elements":[],"widgetType":"heading"},{"id":"907a70c","elType":"widget","settings":{"editor":"<p>For straightforward local moves, wheel-lift recovery is a fast and efficient option. We lift the front or rear wheels off the ground and tow the vehicle safely — ideal for short-distance recovery to a nearby garage or home address.</p>","_css_classes":"x-t x-sc-text"},"elem