"bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true},"css_classes":"x-faq-intro rv x-dc e-no-lazyload","flex_direction":"column"},"elements":[{"id":"a7abe1c","elType":"widget","settings":{"editor":"<p>FAQs</p>","_css_classes":"x-t x-eyebrow"},"elements":[],"widgetType":"text-editor"},{"id":"ad1b72d","elType":"widget","settings":{"title":"Frequently Asked <span class="x-hl">Questions</span>","_css_classes":"x-h x-title"},"elements":[],"widgetType":"heading"},{"id":"bd62888","elType":"widget","settings":{"editor":"<p>Still have a question? Call us any time — day or night.</p>","_css_classes":"x-t x-body"},"elements":[],"widgetType":"text-editor"},{"id":"0dd27a6","elType":"widget","settings":{"text":"Call Now: 07771 004242","link":{"url":"tel:07771004242","is_external":"","nofollow":""},"selected_icon":{"value":"fas fa-phone-alt","library":"fa-solid"},"icon_indent":{"unit":"px","size":10},"_css_classes":"x-btn"},"elements":[],"widgetType":"button"}],"isInner":true},{"id":"def8833","elType":"container","settings":{"content_width":"full","padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"flex_gap":{"unit":"px","size":0,"column":"0","row":"0","isLinked":true},"css_classes":"x-faq-wrap rv rv-right x-dc e-no-lazyload"},"elements":[{"id":"e647cb8","elType":"widget","settings":{"tabs":[{"tab_title":"Do you offer 24/7 breakdown recovery in Birmingham?","tab_content":"<p><span style="font-weight: 400;">Yes. AAD Transport &amp; Recovery operates 24 hours a day, 7 days a week, across Birmingham and the surrounding areas, including emergency breakdowns at any time of day or night.</span></p>","_id":"ee07014"},{"tab_title":"How quickly can you get to me?","tab_content":"<p><span style="font-weight: 400;">Response times depend on your location and current job volume, but we prioritise getting to you as quickly as possible, especially in unsafe roadside situations. Call us directly for the fastest response.</span></p>","_id":"84df15b"},{"tab_title":"Do you tow cars long distances, or just locally? ","tab_content":"<p><span style="font-weight: 400;">Both. We handle local towing within Birmingham as well as long-distance recovery anywhere in the UK.</span></p>","_id":"dea1ce7"},{"tab_title":"What's the difference between flatbed and wheel-lift recovery? ","tab_content":"<p><span style="font-weight: 400;">Flatbed recovery loads the whole vehicle onto a platform, ideal for damaged, low-clearance or non-running vehicles. Wheel-lift recovery tows the vehicle with its wheels partially off the ground and is typically used for quicker, shorter-distance jobs.</span></p>","_id":"9f01fb7"},{"tab_title":"Can you recover my vehicle after an accident? ","tab_content":"<p><span style="font-weight: 400;">Yes. We provide accident recovery, clearing your vehicle from the scene safely and transporting it to a garage, body shop, or your preferred location.</span></p>","_id":"d7ce03c"},{"tab_title":"Do you recover vans and commercial vehicles? ","tab_content":"<p><span style="font-weight: 400;">Yes. We offer commercial vehicle towing and heavy-duty recovery for vans and light commercial vehicles.</span></p>","_id":"6f67734"},{"tab_title":"Can you help with motorbikes, caravans or trailers? ","tab_content":"<p><span style="font-weight: 400;">Yes. We provide dedicated motorcycle recovery as well as RV and trailer recovery for caravans, motorhomes and trailers.</span></p>","_id":"3257de0"},{"tab_title":"What if I just have a flat tyre or flat battery? ","tab_content":"<p><span style="font-weight: 400;">We offer flat tyre assistance, spare tyre fitting, and battery jump-start services. Many of these issues can be resolved at the roadside without needing a full tow.</span></p>","_id":"9ed2352"},{"tab_title":"Do you deliver fuel if I've run out? ","tab_content":"<p><span style="font-weight: 400;">Yes, we provide emergency fuel delivery to get you moving again.</span></p>","_id":"4824e70"},{"tab_title":"Can I choose the garage my car is taken to? ","tab_content":"<p><span style="font-weight: 400;">Yes. If your vehicle needs recovering, it can usually be taken to your garage of choice, a repair centre, your home address, or another safe destination you specify.</span></p>","_id":"35b5dfc"},{"tab_title":"How much does breakdown recovery in Birmingham cost? ","tab_content":"<p><span style="font-weight: 400;">Pricing depends on the type of recovery, distance, and vehicle involved. Call us for a free, no-obligation quote before we begin any work.</span></p>","_id":"c45e059"},{"tab_title":"What areas do you cover? ","tab_content":"<p><span style="font-weight: 400;">We cover Birmingham and the surrounding West Midlands area for local recovery, with long-distance and nationwide transport also available.</span></p>","_id":"e986e87"}],"title_color":"#011D5E","tab_active_color":"#011D5E","content_color":"#4B546E","border_width":{"unit":"px","size":1},"border_color":"#D6DBE7","title_typography_typography":"custom","title_typography_font_family":"Figtree","title_typography_font_weight":"600","title_typography_font_size":{"unit":"px","size":16},"content_typography_typography":"custom","content_typography_font_family":"Figtree","content_typography_font_size":{"unit":"px","size":15},"faq_schema":"yes","title_typography_line_height_mobile":{"unit":"em","size":1.5,"sizes":[]},"title_padding":{"unit":"px","top":"20","right":"10","bottom":"20","left":"10","isLinked":false},"title_padding_tablet":{"unit":"px","top":"20","right":"10","bottom":"20","left":"10","isLinked":false},"title_padding_mobile":{"unit":"px","top":"20","right":"10","bottom":"20","left":"10","isLinked":false},"icon_align":"right","content_padding":{"unit":"px","top":"20","right":"10","bottom":"0","left":"10","isLinked":false},"content_padding_tablet":{"unit":"px","top":"20","right":"10","bottom":"0","left":"10","isLinked":false},"content_padding_mobile":{"unit":"px","top":"20","right":"10",